#pragma once

#include <cstdio>
#include <string>

class LogFile {
public:
  explicit LogFile(const std::string& path) : fp_(std::fopen(path.c_str(), "a")) {}
  ~LogFile() { if (fp_ != nullptr) std::fclose(fp_); }

  void write(const std::string& line) { std::fputs(line.c_str(), fp_); }

private:
  std::FILE* fp_;
};

